    const protagonistSkillsSheet = {
        uid: "sheet_lEARaBa8",
        name: "主角技能表",
        sourceData: {
            note: "记录主角获得的所有技能项目。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 技能名称 - 技能的名称，不得与表中已有技能重名。\n- 列1: 技能类型 - 技能的类别（如：\u201C被动\u201D、\u201C主动\u201D）。\n- 列2: 等级/阶段 - 技能的当前等级或阶段。\n- 列3: 效果描述 - 技能在当前等级下的具体效果。",
