    const inventorySheet = {
        uid: "sheet_in05z9vz",
        name: "背包物品表",
        sourceData: {
            note: "记录主角拥有的所有物品、装备。（列号为 0 基，与表格数据中的列标一致）\n- 列0: 物品名称 - 物品的名称，不得与表中已有物品重名。\n- 列1: 数量 - 拥有的数量。\n- 列2: 描述/效果 - 物品的功能或背景描述。\n- 列3: 类别 - 物品的类别（如：\u201C武器\u201D、\u201C消耗品\u201D、\u201C杂物\u201D）。",
