                    method: 'POST',
                    headers,
                    body: JSON.stringify({ avatar_url: avatar, simple: true }),
                });
                if (!response.ok) {
                    logWarn_ACU(`[ChatGateway] 枚举角色聊天失败（HTTP ${response.status}）：${avatar}`);
                    return null;
