        if (!rootMessage) {
            return { ok: false, code: 'root_missing', error: `provisional root 楼层 ${bridge.provisionalRootIndex} 不存在，无法推进提交进度。` };
        }
        writeProvisionalBridgeToMessage_ACU(rootMessage, isolationKey, nextBridge);
