                createdAt: now,
                reason: 'manual',
                data: provisionalData,
                event: { filledSheetKeys: [], changedSheetKeys: [], groupKeys: [] },
                context: { messageIndex: rangeStartMessageIndex, aiFloor: 1, isolationKey, reason: 'manual' },
            });
