     */
    function isSameSheetHeader_ACU(left, right) {
        if (!Array.isArray(left) || !Array.isArray(right))
            return false;
        if (left.length !== right.length)
            return false;
        for (let i = 0; i < left.length; i++) {
            if (String(left[i] ?? '') !== String(right[i] ?? ''))
                return false;
        }
        return true;
    }
    /**
