                                next.sourceData = JSON.parse(JSON.stringify(guideSheet.sourceData));
                            if (guideSheet?.updateConfig)
                                next.updateConfig = JSON.parse(JSON.stringify(guideSheet.updateConfig));
                            if (guideSheet?.exportConfig)
