                displayTableName: String(beforeSheet.name || sheetKey),
                physicalTableName,
                beforeContent,
                afterContent: Array.isArray(afterContent) ? afterContent : null,
                identities,
                displayToPhysicalCol: chineseToSql,
                physicalColTypes,
