            get(_target, propName) {
                // 静态方法：db.expr("SQL表达式") — 执行任意 SQL 表达式
                if (propName === 'expr')
                    return execExpr;
                // 静态方法：db.rand(min, max) — 生成随机整数
                if (propName === 'rand')
                    return execRand;
                // 静态方法：db.calc("算术表达式") — 执行含 $v: 变量引用的算术表达式
                if (propName === 'calc')
                    return execCalc;
                // 静态方法：db.max(值1, 值2, ...) — 取多个值中的最大值
                if (propName === 'max')
                    return execMax;
                // 静态方法：db.min(值1, 值2, ...) — 取多个值中的最小值
                if (propName === 'min')
                    return execMin;
