            const sql = `SELECT ${translatedExpr}`;
            const provider = getStorageProvider();
            const result = provider.executeQuery(sql);
            if (result.values.length === 0)
                return null;
            const val = result.values[0][0];
            if (val === null || val === undefined)
                return null;
            if (typeof val === 'number')
                return val;
            return String(val);
