        if (!ifStartMatch)
            return null;
        const ifStartTagEnd = startIndex + ifStartMatch[0].length;
        let nestingLevel = 1;
        let currentIndex = ifStartTagEnd;
        while (currentIndex < content.length && nestingLevel > 0) {
            const remainingContent = content.slice(currentIndex);
            const nestedIfMatch = remainingContent.match(/<if\s+(?:seed|cell|cond|db|sql)\s*=\s*"[^"]*"\s*>/i);
            const endIfMatch = remainingContent.match(/<\/if>/i);
            const elseMatch = remainingContent.match(/<else>/i);
            const positions = [];
            if (nestedIfMatch)
                positions.push({ type: 'if', index: currentIndex + nestedIfMatch.index, length: nestedIfMatch[0].length });
            if (endIfMatch)
                positions.push({ type: 'endif', index: currentIndex + endIfMatch.index, length: endIfMatch[0].length });
            if (elseMatch && nestingLevel === 1)
                positions.push({ type: 'else', index: currentIndex + elseMatch.index, length: elseMatch[0].length });
            if (positions.length === 0) {
