                    const hasWrapperBefore = !!(wrapperParts && wrapperParts.before);
                    const hasWrapperAfter = !!(wrapperParts && wrapperParts.after);
                    const use3DepthWrapperGroup = !!(useWrapperEntries && (hasWrapperBefore || hasWrapperAfter));
