                    committedBucketCount += result.committedBucketCount;
                    if (!result.success) {
                        const outcome = result.aborted ? 'stopped' : undefined;
                        const primaryError = result.error || (result.aborted ? '手动追平已终止。' : '手动追平失败。');
                        // 终态不变量：stopped/failed 只能在 staging 已汇合或丢弃后写入。
