     * 休眠完整性自检（S3-3）：校验每个 hidden 表的恢复来源可达，发现孤儿即报告。
     *
     * 纯只读，不做任何修复或写入。判定语义与唤醒守卫（evaluateWakeGuards_ACU 首条）
     * 及 compaction 前滚的 fail-closed 条件（隐藏表缺 restoreSourceData 时拒绝写边界）
     * 保持同源：审计报警的表，唤醒必然被拦、边界前滚必然失败——
     * 及早警告让用户在旧楼层仍在（数据仍可抢救）时处理，而不是事后才暴露。
     *
     * indeterminate 生命周期（无法判定 active/hidden）同样计入警告面：
     * 它意味着该表的历史 checkpoint 链不完整，恢复来源不可达。
     */
    function auditDormantDataIntegrity_ACU() {
        const chat = getChatArray_ACU();
        const isolationKey = getCurrentIsolationKey_ACU();
        let lifecycle;
        try {
            lifecycle = deriveSheetLifecycleFromFramesV2_ACU(chat, isolationKey);
        }
        catch (e) {
            return {
                ok: false,
                issues: [],
                hiddenCount: 0,
                error: `无法读取表格历史（生命周期派生失败）：${e instanceof Error ? e.message : String(e)}`,
            };
        }
        const issues = [];
        for (const sheetKey of lifecycle.hiddenSheetKeys) {
            const entry = lifecycle.statusBySheetKey[sheetKey];
            const restore = entry?.restoreSourceData;
            if (!restore) {
                issues.push({
                    sheetKey,
                    name: sheetKey,
                    kind: 'missing_restore_data',
                    message: `休眠表 ${sheetKey} 的恢复数据缺失：找不到对应的休眠 checkpoint，该表无法唤醒，且在旧楼层被清理后数据将永久丢失。`,
                });
                continue;
            }
            if (!Array.isArray(restore.content) || !Array.isArray(restore.content[0])) {
                const name = String(restore.name ?? '') || sheetKey;
                issues.push({
                    sheetKey,
                    name,
                    kind: 'corrupt_restore_data',
                    message: `休眠表「${name}」的恢复数据已损坏（缺少有效表头），该表无法唤醒；请在旧楼层被清理前导出备份。`,
                });
            }
        }
        for (const sheetKey of lifecycle.indeterminateSheetKeys) {
            issues.push({
                sheetKey,
                name: sheetKey,
                kind: 'indeterminate_lifecycle',
                message: `表 ${sheetKey} 的生命周期无法判定（历史 checkpoint 链不完整），其休眠数据的恢复来源不可达。`,
            });
        }
        return { ok: true, issues, hiddenCount: lifecycle.hiddenSheetKeys.length };
    }
    /**
     * 唤醒一个休眠表：把它的 header-only 结构壳并入当前运行时模板快照，
     * 经协调器应用——协调器识别到模板含派生 key 命中生命周期 hidden 的表后
     * 产出 reveal 变更，持久层从 hide checkpoint 恢复离开时的完整数据（S1-4 再协调对齐结构）。
     *
     * 守卫（与 listDormantTables_ACU 的 canWake 判定一致，fail-loud）：
     * 快照存在且结构有效、派生 key 与历史 key 一致、当前模板无 canonical 同名表。
     */
    async function wakeDormantTable_ACU(sheetKey, options = {}) {
        const chat = getChatArray_ACU();
        const isolationKey = getCurrentIsolationKey_ACU();
        let lifecycle;
        try {
            lifecycle = deriveSheetLifecycleFromFramesV2_ACU(chat, isolationKey);
        }
        catch (e) {
            return { saved: false, error: `无法读取表格历史（生命周期派生失败）：${e instanceof Error ? e.message : String(e)}` };
        }
        const entry = lifecycle.statusBySheetKey[sheetKey];
        if (!entry || entry.status !== 'hidden') {
            return { saved: false, error: `表 ${sheetKey} 当前不处于休眠状态，无法唤醒。` };
        }
        const snapshot = getRuntimeTemplateSnapshot_ACU();
        const guards = evaluateWakeGuards_ACU(sheetKey, entry.restoreSourceData, snapshot?.templateObj ?? null);
        if (!guards.canWake) {
            return { saved: false, error: guards.reason || '该休眠表当前不可唤醒。' };
        }
        // header-only 壳：保留结构（表头/DDL/隐藏集/别名/配置），剥掉数据行——
        // 数据由 reveal 链路从 hide checkpoint 权威恢复，模板携带数据行反而会造成重复合并语义。
        const shell = deepClone_ACU(entry.restoreSourceData);
        shell.content = [shell.content[0]];
        const templateObj = deepClone_ACU(snapshot.templateObj);
        templateObj[sheetKey] = shell;
        return await applyChatTemplateSnapshotWithReconciliation_ACU(templateObj, {
            source: 'dormant_wake_table',
            presetName: resolveActiveTemplatePresetName_ACU({ fallbackToGlobal: true, isolationKey }),
            signal: options.signal,
        });
    }
    /**
     * 唤醒一个休眠列：从当前运行时模板快照中该表的 hiddenPhysicalColumns 移除目标项
     * （大小写不敏感精确匹配隐藏集条目），经协调器应用——该列成为目标可见列后由
     * canonical 匹配复活其数据。
     */
    async function wakeDormantColumn_ACU(sheetKey, hiddenName, options = {}) {
        const requested = String(hiddenName ?? '').trim();
        if (!requested)
            return { saved: false, error: '未指定要唤醒的休眠列。' };
        const snapshot = getRuntimeTemplateSnapshot_ACU();
        if (!snapshot?.templateObj) {
            return { saved: false, error: '当前运行时模板不可用，无法唤醒休眠列。' };
        }
        const templateObj = deepClone_ACU(snapshot.templateObj);
        const sheet = templateObj[sheetKey];
        if (!sheet || typeof sheet !== 'object') {
            return { saved: false, error: `当前模板中不存在表 ${sheetKey}，无法唤醒其休眠列。` };
        }
        const rawHidden = sheet.sourceData?.hiddenPhysicalColumns;
        const hidden = Array.isArray(rawHidden) ? rawHidden.map(value => String(value ?? '')) : [];
        const requestedCanonical = requested.toLowerCase();
        const remaining = hidden.filter(value => value.trim().toLowerCase() !== requestedCanonical);
        if (remaining.length === hidden.length) {
            return { saved: false, error: `列「${requested}」不在表「${String(sheet.name ?? sheetKey)}」的休眠集中，无法唤醒。` };
        }
        if (!sheet.sourceData || typeof sheet.sourceData !== 'object') {
            return { saved: false, error: `表 ${sheetKey} 缺少 sourceData，休眠集状态异常。` };
        }
        if (remaining.length > 0) {
            sheet.sourceData.hiddenPhysicalColumns = remaining;
        }
        else {
            delete sheet.sourceData.hiddenPhysicalColumns;
        }
        return await applyChatTemplateSnapshotWithReconciliation_ACU(templateObj, {
            source: 'dormant_wake_column',
            presetName: resolveActiveTemplatePresetName_ACU({ fallbackToGlobal: true }),
            signal: options.signal,
        });
    }

    /**
     * service/plot/plot-orchestrator.ts — 剧情推进编排逻辑（service 层：纯业务决策）
     * 从 presentation/bootstrap/init.ts 的 GENERATION_AFTER_COMMANDS 回调提取。
     *
     * 负责：判断是否应该进行剧情规划、调用规划逻辑、返回规划结果。
     * 不负责：写回消息、清空输入框、停止生成等 UI 操作。
     */
    // ============================================================
    // 核心业务函数
    // ============================================================
    /**
     * 判断 TavernHelper.generate 钩子是否应该进行剧情规划
     * 纯业务逻辑
     */
    function shouldProcessTavernHelperHook_ACU(options) {
        if (!settings_ACU.plotSettings.enabled || isFlightModeActive_ACU() || isProcessing_Plot_ACU || loopState_ACU.isRetrying || options.should_stream) {
            return false;
        }
        return true;
    }
    /**
     * 从 TavernHelper.generate 的 options 中提取用户消息
     * 纯业务逻辑
     */
    function extractUserMessageFromOptions_ACU(options) {
        let userMessage = options.user_input || options.prompt;
        if (options.injects?.[0]?.content) {
            userMessage = options.injects[0].content;
        }
        return userMessage || null;
    }
    /**
     * 处理规划结果并决定如何写回 TavernHelper.generate 的 options
     * 纯业务逻辑：返回应该写回的位置和内容
     */
    function applyPlanningResultToOptions_ACU(options, finalMessage) {
        if (options.injects?.[0]?.content) {
            return { target: 'injects', value: finalMessage };
        }
        else if (options.prompt) {
            return { target: 'prompt', value: finalMessage };
        }
        else {
            return { target: 'user_input', value: finalMessage };
        }
    }
    /**
     * 处理循环模式下规划失败的情况
     * 纯业务逻辑
     * @returns true 表示应该进入重试流程
     */
    function shouldEnterLoopRetryOnPlanningFailure_ACU(finalMessage) {
        return (loopState_ACU.isLooping &&
            loopState_ACU.awaitingReply &&
            (!finalMessage || typeof finalMessage !== 'string'));
    }
    /**
     * 为策略1（已有用户消息）准备规划上下文
     * 纯业务逻辑
     */
    function prepareStrategy1Context_ACU(lastMessage) {
        if (!lastMessage || !lastMessage.is_user || lastMessage._plot_processed) {
            return null;
        }
        const messageToProcess = lastMessage.mes;
        if (!messageToProcess || !messageToProcess.trim()) {
            return null;
        }
        lastMessage._plot_processed = true;
        const originalInputHash = hashUserInput_ACU(messageToProcess);
        lastMessage._qrf_plot_pending_hash = originalInputHash;
        logDebug_ACU('[剧情推进] [Plot] 在消息对象上保存原始输入哈希:', originalInputHash);
        return { messageToProcess, originalInputHash };
    }
    // ============================================================
    // TavernHelper.generate hook 编排
    // ============================================================
    /**
     * TavernHelper.generate hook 的完整业务编排
     *
     * 职责：判断是否处理 → 提取用户消息 → 标记拦截 → 调用规划 → 判断循环重试 → 决定写回位置
     * 不负责：修改 options 对象、调用原始 generate 函数（这些由 presentation 层做）
     */
    async function orchestrateTavernHelperHook_ACU(options, runPlanning) {
        // 1. 判断是否应该处理
        if (!shouldProcessTavernHelperHook_ACU(options)) {
            return { action: 'passthrough' };
        }
        // 2. 提取用户消息
        const userMessage = extractUserMessageFromOptions_ACU(options);
        if (!userMessage) {
            return { action: 'passthrough' };
        }
        // 3. 标记拦截（供 GENERATION_AFTER_COMMANDS 去重）
        markPlotIntercept_ACU(userMessage);
        // 4. 调用规划
        _set_isProcessing_Plot_ACU(true);
        try {
            const finalMessage = await runPlanning(userMessage, {
                originalUserInput: userMessage,
                hasExistingUserMessage: false,
            });
            // 5. 处理跳过
            if (finalMessage && finalMessage.skipped) {
                logDebug_ACU('[剧情推进] Planning skipped in TavernHelper.generate hook (duplicate).');
                return { action: 'skipped' };
            }
            // 6. 处理中止
            if (finalMessage && finalMessage.aborted) {
                logDebug_ACU('[剧情推进] Generation aborted by user.');
                return { action: 'aborted' };
            }
            // 7. 判断循环模式下规划失败
            if (shouldEnterLoopRetryOnPlanningFailure_ACU(finalMessage)) {
                logWarn_ACU('[剧情推进] [Loop] 规划未产生有效回复，按循环重试规则重试。');
                return { action: 'loop_retry' };
            }
            // 8. 规划成功，决定写回位置
            if (finalMessage && typeof finalMessage === 'string') {
                const writeBack = applyPlanningResultToOptions_ACU(options, finalMessage);
                return { action: 'planned', finalMessage, writeBack };
            }
            // 9. 规划返回 null（未启用/失败），透传
            return { action: 'passthrough' };
        }
        catch (error) {
            logError_ACU('[剧情推进] Error in TavernHelper.generate hook orchestration:', error);
            return { action: 'passthrough' };
        }
        finally {
            _set_isProcessing_Plot_ACU(false);
        }
    }
    // ============================================================
    // GENERATION_AFTER_COMMANDS 策略1编排
    // ============================================================
    /**
     * 策略1：处理已存在的用户消息（/send 等命令先创建消息再触发生成）
     *
     * 职责：准备上下文 → 标记循环 → 调用规划 → 判断循环重试 → 返回结果
     * 不负责：写回 params.prompt、更新消息、清空输入框、停止生成、删除消息（这些由 presentation 层做）
     */
    async function orchestrateAfterCommandsStrategy1_ACU(lastMessage, lastMessageIndex, runPlanning) {
        // 1. 准备策略1上下文
        const context = prepareStrategy1Context_ACU(lastMessage);
        if (!context) {
            return { action: 'no_match' };
        }
        const { messageToProcess, originalInputHash } = context;
        // 2. 标记循环模式
        const isLoopTriggered = loopState_ACU.isLooping && loopState_ACU.awaitingReply;
        if (isLoopTriggered) {
            lastMessage._qrf_from_planning = true;
            logDebug_ACU('[剧情推进] [Loop] 标记规划层消息: _qrf_from_planning=true');
        }
        // 3. 调用规划
        _set_isProcessing_Plot_ACU(true);
        try {
            const finalMessage = await runPlanning(messageToProcess, {
                originalUserInput: messageToProcess,
                hasExistingUserMessage: true,
            });
            // 4. 处理跳过
            if (finalMessage && finalMessage.skipped) {
                logDebug_ACU('[剧情推进] Planning skipped in Strategy 1 (duplicate).');
                return { action: 'skipped' };
            }
            // 5. 处理中止
            if (finalMessage && finalMessage.aborted) {
                logDebug_ACU('[剧情推进] Generation aborted by user in Strategy 1.');
                return {
                    action: 'aborted',
                    manual: finalMessage.manual,
                    restoreText: finalMessage.restoreText ?? messageToProcess,
                    originalMessage: messageToProcess,
                    lastMessageIndex,
                };
            }
            // 6. 判断循环模式下规划失败
            if (shouldEnterLoopRetryOnPlanningFailure_ACU(finalMessage)) {
                logWarn_ACU('[剧情推进] [Loop] 规划未产生有效回复，按循环重试规则重试。');
                return { action: 'loop_retry' };
            }
            // 7. 规划成功
            if (finalMessage && typeof finalMessage === 'string') {
                return {
                    action: 'planned',
                    finalMessage,
                    originalMessage: messageToProcess,
                    lastMessageIndex,
                };
            }
            // 8. 规划返回 null
            return { action: 'no_match' };
        }
        catch (error) {
            logError_ACU('[剧情推进] Error processing last chat message:', error);
            delete lastMessage._plot_processed;
            return { action: 'no_match' };
        }
        finally {
            _set_isProcessing_Plot_ACU(false);
        }
    }
    // ============================================================
    // GENERATION_AFTER_COMMANDS 策略2编排
    // ============================================================
    /**
     * 策略2：处理输入框中的文本（正常发送路径，用户楼层还未写入 chat）
     *
     * 职责：调用规划 → 返回结果
     * 不负责：读取/写回输入框、停止生成（这些由 presentation 层做）
     */
    async function orchestrateAfterCommandsStrategy2_ACU(textInBox, runPlanning) {
        if (!textInBox || !String(textInBox).trim()) {
            return { action: 'skip' };
        }
        const originalInputText = String(textInBox);
        _set_isProcessing_Plot_ACU(true);
        try {
            const finalMessage = await runPlanning(originalInputText, {
                originalUserInput: originalInputText,
                hasExistingUserMessage: false,
            });
            // 处理跳过
            if (finalMessage && finalMessage.skipped) {
                logDebug_ACU('[剧情推进] Planning skipped in Strategy 2 (duplicate).');
                return { action: 'skip' };
            }
            // 处理中止
            if (finalMessage && finalMessage.aborted) {
                logDebug_ACU('[剧情推进] Generation aborted by user in Strategy 2.');
                return { action: 'aborted', manual: finalMessage.manual };
            }
            // 规划成功
            if (finalMessage && typeof finalMessage === 'string') {
                return { action: 'planned', finalMessage };
            }
            return { action: 'skip' };
        }
        catch (error) {
            logError_ACU('[剧情推进] Error processing textarea input (Strategy 2):', error);
            return { action: 'skip' };
        }
        finally {
            _set_isProcessing_Plot_ACU(false);
            // 消费掉本次发送意图，避免同一次生成链路重复触发
            // 注意：generationGate 的重置由 presentation 层负责（因为它涉及 UI 状态）
        }
    }

