            }
            else {
                logWarn_ACU('[剧情推进] 未找到中止按钮元素。');
            }
        }, 200);
        // 3. 调用 service 层纯函数
        const result = await runOptimizationLogic_ACU(userMessage, options);
        // 4. 清除进度 toast
        try {
            if ($toast)
                toastr_API_ACU.clear($toast);
        }
        catch (e) { }
        // 5. 根据结果做 UI 通知
        if (!result) {
            return null;
        }
        // 跳过的情况（retrying / inflight / disabled）—— 不弹 toast，静默返回
        if (result.skipped) {
            return result.reason === 'inflight' ? { skipped: true } : null;
        }
        // 用户中止
        if (result.aborted) {
            return { aborted: true, manual: result.manual, restoreText: result.restoreText };
        }
        // 失败：根据 errorType 弹对应 toast
        if (!result.success) {
            const errorMsg = result.errorMessage || '剧情规划失败。';
            if (result.errorType === 'stage_failure' || result.errorType === 'all_failed' || result.errorType === 'no_tasks') {
                showToastr_ACU('error', errorMsg, '规划失败', {
                    acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR,
                });
            }
            else if (result.errorType === 'exception') {
                showToastr_ACU('error', errorMsg, '规划失败', {
                    acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR,
                });
            }
            return null;
        }
        // 成功：弹结果 toast
        if (result.aggregatedTagNames && result.aggregatedTagNames.length > 0) {
            showToastr_ACU('info', `已成功聚合 [${result.aggregatedTagNames.join(', ')}] 标签内容并注入。`, '标签摘取');
        }
        if (result.hasPartialFailure) {
            showToastr_ACU('warning', `剧情规划完成，${result.successCount}/${result.enabledTaskCount} 个任务成功。`, '部分成功', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.PLAN_OK });
        }
        else {
            showToastr_ACU('success', `剧情规划成功，共完成 ${result.successCount} 个任务。`, '规划成功', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.PLAN_OK });
        }
        return result.finalMessage;
    }

    /** Rerank 请求超时上界；超时抛错由调用方回退到 embedding 排序。 */
    const VECTOR_RERANK_TIMEOUT_MS_ACU = 30000;
    function normalizeEndpoint_ACU(endpoint) {
        return String(endpoint || '').trim().replace(/\/+$/, '');
    }
    function buildRerankHeaders_ACU(apiKey) {
        const headers = {
            ...getHostRequestHeaders_ACU(),
            'Content-Type': 'application/json',
        };
        if (apiKey) {
            headers.Authorization = `Bearer ${apiKey}`;
        }
        return headers;
    }
    function normalizeRerankItem_ACU(item, fallbackIndex) {
        if (!item || typeof item !== 'object') {
            return null;
        }
        const rawIndex = item.index ?? item.document_index ?? item.documentIndex;
        const rawScore = item.relevance_score ?? item.relevanceScore ?? item.score ?? item.rerank_score;
        const index = Number.isFinite(Number(rawIndex)) ? Math.floor(Number(rawIndex)) : fallbackIndex;
        const relevanceScore = Number(rawScore);
        if (!Number.isFinite(index) || index < 0 || !Number.isFinite(relevanceScore)) {
            return null;
        }
        return {
            index,
            relevanceScore,
        };
    }
    function extractRerankResults_ACU(payload) {
        const rawResults = Array.isArray(payload?.results)
            ? payload.results
            : Array.isArray(payload?.data?.results)
                ? payload.data.results
                : Array.isArray(payload?.data)
                    ? payload.data
                    : [];
        return rawResults
            .map((item, index) => normalizeRerankItem_ACU(item, index))
            .filter((item) => !!item);
    }
    async function createRerankScores_ACU(request) {
        const endpoint = normalizeEndpoint_ACU(request.endpoint);
        const model = String(request.model || '').trim();
        const query = String(request.query || '').trim();
        const documents = Array.isArray(request.documents)
            ? request.documents.map((item) => String(item ?? '').trim())
            : [];
        if (!endpoint) {
            throw new Error('Rerank endpoint 为空。');
        }
        if (!model) {
            throw new Error('Rerank model 为空。');
        }
        if (!query) {
            return [];
        }
        if (documents.length === 0 || documents.every((item) => !item)) {
            return [];
        }
        const instruction = String(request.instruction ?? '').trim();
        const payload = { model, query, documents };
        if (instruction)
            payload.instruction = instruction;
        // 超时可中断：rerank 在发送前同步链路上，挂起的上游不允许无限阻塞生成。
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), VECTOR_RERANK_TIMEOUT_MS_ACU);
        let response;
        try {
            response = await fetch(endpoint, {
                method: 'POST',
                headers: buildRerankHeaders_ACU(request.apiKey),
                body: JSON.stringify(payload),
                signal: controller.signal,
            });
        }
        catch (error) {
            throw new Error(error?.name === 'AbortError'
                ? `Rerank 请求超时（${VECTOR_RERANK_TIMEOUT_MS_ACU}ms），已中断。`
                : `Rerank 请求网络失败：${error?.message || String(error || '未知错误')}`);
        }
        finally {
            clearTimeout(timer);
        }
        if (!response.ok) {
            const detail = await response.text().catch(() => response.statusText);
            throw new Error(`Rerank 请求失败: ${response.status} ${detail}`);
        }
        const rawBody = await response.text().catch(() => '');
        let responsePayload;
        try {
            responsePayload = JSON.parse(rawBody);
        }
        catch (_error) {
            throw new Error(`Rerank 响应不是合法 JSON（前 200 字符：${rawBody.slice(0, 200)}）。`);
        }
        return extractRerankResults_ACU(responsePayload);
    }

    function getCurrentSummaryVectorIndexSourceTableKey_ACU() {
        const tables = currentJsonTableData_ACU && typeof currentJsonTableData_ACU === 'object'
            ? currentJsonTableData_ACU
            : null;
        if (!tables)
            return 'summary';
        return Object.keys(tables).find((key) => {
            const table = tables[key];
            return !!table?.name && isSummaryOrOutlineTable_ACU(String(table.name || ''));
        }) || 'summary';
    }
    /**
     * 当聊天 tag data 缺少索引指针时，从唯一可证明属于当前 canonical scope 的外部快照恢复。
     *
     * 这是聊天/向量持久化逻辑，不属于任何 UI。V2 只接受 registry 中已 durable-published 的
     * 快照；legacy 格式没有可靠的修订序，只接受唯一可信候选，避免用文件名顺序猜测数据新旧。
     */
    function getUniqueSummaryVectorIndexSourceTableKeyForRecovery_ACU() {
        const tables = currentJsonTableData_ACU && typeof currentJsonTableData_ACU === 'object'
            ? currentJsonTableData_ACU
            : null;
        if (!tables)
            return '';
        const candidates = Object.keys(tables).filter((key) => {
            const table = tables[key];
            return !!table?.name && isSummaryOrOutlineTable_ACU(String(table.name || ''));
        });
        return candidates.length === 1 ? candidates[0] : '';
    }
    async function tryRecoverSummaryVectorIndexFromExternalSnapshot_ACU() {
        const chatKey = String(currentChatFileIdentifier_ACU || '').trim();
        // 标签隔离已退役：未开启时 isolationKey 为 ''，空串是合法默认槽，不能当缺失。
        const isolationKey = String(getCurrentIsolationKey_ACU() ?? '');
        const sourceTableKey = getUniqueSummaryVectorIndexSourceTableKeyForRecovery_ACU();
        if (!chatKey || !sourceTableKey)
            return false;
        const chatName = getCurrentCharacterCardName_ACU();
        const registeredFiles = await loadVectorIndexRegistry_ACU()
            .then((registry) => Array.isArray(registry.files) ? registry.files : [])
            .catch((error) => {
            logWarn_ACU('[交火模式纪要索引] 自动恢复读取 V2 registry 失败，将继续尝试 legacy 路径:', error);
            return [];
        });
        const restoreCandidate = async (blob, manifest) => {
            const chat = getChatArray_ACU();
            if (!Array.isArray(chat) || chat.length === 0)
                return false;
            const targetIndex = chat.map((message, index) => message && !message.is_user ? index : -1)
                .filter((index) => index >= 0)
                .pop() ?? -1;
            if (targetIndex < 0)
                return false;
            const message = chat[targetIndex];
            if (readIsolatedTagData_ACU(message, isolationKey)?.summaryVectorIndexState?.manifest?.indexId)
                return false;
            const rows = Array.isArray(blob.rows) ? blob.rows : [];
            const chunks = Array.isArray(blob.chunks) ? blob.chunks : [];
            const nextState = {
                version: 1,
                backend: 'st-files',
                status: 'ready',
                indexId: String(manifest.indexId),
                snapshotMessageId: String(manifest.snapshotMessageId || message.mesId || ''),
                sourceTableKey: String(manifest.sourceTableKey || sourceTableKey),
                sourceTableName: String(manifest.sourceTableName || sourceTableKey),
                indexedAt: String(manifest.indexedAt || new Date().toISOString()),
                rowCount: rows.filter((row) => row.status !== 'removed').length,
                chunkCount: chunks.length,
                skippedRowCount: 0,
                rows,
                chunks: chunks.map((chunk) => ({
                    ...chunk,
                    // 统一归一为普通 number[]：state.chunks 会随聊天元数据 JSON 序列化，
                    // 不能把 Float32Array 落进持久化路径。
                    vector: Array.isArray(chunk.vector) || chunk.vector instanceof Float32Array
                        ? Array.from(chunk.vector, (item) => Number(item)).filter((item) => Number.isFinite(item))
                        : [],
                })),
                manifest: JSON.parse(JSON.stringify(manifest)),
            };
            try {
                // CAS：目标槽当前必须不存在有效 indexId，防止外部读取期间已有新 pointer。
                return await commitVectorMetadataPatch_ACU(message, isolationKey, {
                    summaryVectorIndexState: nextState,
                    summaryVectorIndexManifest: JSON.parse(JSON.stringify(manifest)),
                }, {
                    expectedIndexId: '',
                });
            }
            catch (error) {
                logWarn_ACU('[交火模式纪要索引] 自动恢复持久化失败，已回滚写前 state:', error);
                return false;
            }
        };
        const v2PathPrefix = `TavernDB_ACU_vector_v2_${buildVectorIndexSingleSnapshotV2ScopeToken_ACU({ chatKey, isolationKey, sourceTableKey })}_`;
        const v2Candidates = [];
        for (const file of registeredFiles) {
            const path = String(file?.path || '').trim();
            if (!path.startsWith(v2PathPrefix) || file?.publicationState !== 'published')
                continue;
            try {
                const loaded = await readVectorIndexJsonFile_ACU(path);
                const blob = loaded.data;
                const manifest = blob?.manifest;
                if (!loaded.ok || !blob || blob.schema !== 'single_file_snapshot' || !manifest?.indexId || manifest.status !== 'ready')
                    continue;
                if (String(manifest.chatKey || '') !== chatKey || String(manifest.isolationKey || '') !== isolationKey || String(manifest.sourceTableKey || '') !== sourceTableKey)
                    continue;
                validateSingleFileSnapshotIdentity_ACU(manifest, blob, path);
                const revision = Number(manifest.storageIdentity?.revision ?? manifest.snapshot?.revision);
                if (Number.isInteger(revision) && revision >= 1)
                    v2Candidates.push({ path, blob, manifest, revision });
            }
            catch { /* 单个 registry 对象不可信时继续审阅同 scope 的其他 published 候选。 */ }
        }
        if (v2Candidates.length > 0) {
            const newestRevision = Math.max(...v2Candidates.map((candidate) => candidate.revision));
            const newestCandidates = v2Candidates.filter((candidate) => candidate.revision === newestRevision);
            if (newestCandidates.length !== 1) {
                logWarn_ACU('[交火模式纪要索引] 自动恢复拒绝同 scope 同 revision 的多个 published V2 候选:', {
                    scope: v2PathPrefix, revision: newestRevision, paths: newestCandidates.map((candidate) => candidate.path),
                });
                return false;
            }
            return restoreCandidate(newestCandidates[0].blob, newestCandidates[0].manifest);
        }
        const legacyPaths = new Set([
            buildVectorIndexSingleSnapshotFilePath_ACU({ chatKey, isolationKey, sourceTableKey, chatName }),
            buildVectorIndexSingleSnapshotFilePath_ACU({ chatKey, isolationKey, sourceTableKey }),
            buildLegacyVectorIndexSingleSnapshotFilePath_ACU({ chatKey, isolationKey, sourceTableKey }),
        ]);
        const legacyCandidates = [];
        for (const path of legacyPaths) {
            try {
                const loaded = await readVectorIndexJsonFile_ACU(path);
                const blob = loaded.data;
                const manifest = blob?.manifest;
                if (!loaded.ok || !blob || blob.schema !== 'single_file_snapshot' || !manifest?.indexId || manifest.status !== 'ready')
                    continue;
                if (String(manifest.chatKey || '') !== chatKey || String(manifest.isolationKey || '') !== isolationKey || String(manifest.sourceTableKey || '') !== sourceTableKey)
                    continue;
                validateSingleFileSnapshotIdentity_ACU(manifest, blob, path);
                legacyCandidates.push({ path, blob, manifest });
            }
            catch { /* 当前候选不可信，继续同 scope 的下一个候选。 */ }
        }
        if (legacyCandidates.length !== 1) {
            if (legacyCandidates.length > 1) {
                logWarn_ACU('[交火模式纪要索引] 自动恢复拒绝多个可信 legacy 快照候选:', {
                    paths: legacyCandidates.map((candidate) => candidate.path),
                });
            }
            return false;
        }
        return restoreCandidate(legacyCandidates[0].blob, legacyCandidates[0].manifest);
    }
    async function clearSummaryVectorIndexLayerFromChat_ACU(params) {
        const chat = getChatArray_ACU();
        const message = Array.isArray(chat) ? chat[params.messageIndex] : null;
        if (!message || message.is_user)
            return false;
        const tagData = readIsolatedTagData_ACU(message, params.isolationKey);
        if (!tagData || typeof tagData !== 'object')
            return false;
        const manifest = tagData.summaryVectorIndexManifest || tagData.summaryVectorIndexState?.manifest || null;
        if (!manifest || String(manifest.indexId || '') !== String(params.indexId || ''))
            return false;
        try {
            return await commitVectorMetadataPatch_ACU(message, params.isolationKey, {
                summaryVectorIndexState: null,
                summaryVectorIndexManifest: null,
            }, {
                expectedIndexId: params.indexId,
            });
        }
        catch (error) {
            throw error;
        }
    }
    async function deleteCurrentSummaryVectorIndexFromChat_ACU() {
        const snapshot = getAggregatedSummaryVectorIndexSnapshot_ACU();
        const chat = getChatArray_ACU();
        const scopeHints = new Map();
        const entries = [];
        if (snapshot?.layers?.length) {
            for (const layer of snapshot.layers) {
                const message = chat[layer.messageIndex];
                if (!message || message.is_user)
                    continue;
                const tagData = readIsolatedTagData_ACU(message, layer.isolationKey);
                if (!tagData)
                    continue;
                const manifest = tagData.summaryVectorIndexManifest || tagData.summaryVectorIndexState?.manifest || null;
                if (manifest) {
                    const hint = {
                        chatKey: manifest.chatKey || currentChatFileIdentifier_ACU,
                        isolationKey: manifest.isolationKey || layer.isolationKey,
                        sourceTableKey: manifest.sourceTableKey || getCurrentSummaryVectorIndexSourceTableKey_ACU(),
                    };
                    scopeHints.set(`${hint.chatKey || ''}\n${hint.isolationKey}\n${hint.sourceTableKey}`, hint);
                }
                entries.push({
                    message,
                    isolationKey: layer.isolationKey,
                    patch: { summaryVectorIndexState: null, summaryVectorIndexManifest: null },
                    expectedIndexId: manifest?.indexId,
                });
            }
        }
        const changed = await commitVectorMetadataPatchesBatch_ACU(entries);
        const scopeHintList = Array.from(scopeHints.values());
        for (const hint of scopeHintList) {
            await deleteSummaryVectorHotCacheByScope_ACU(hint);
            await clearSummaryVectorFlushTasksByScope_ACU(hint);
        }
        const gcResult = await cleanupUnreachableSummaryVectorIndexFiles_ACU({ scopeHints: scopeHintList });
        return changed || gcResult.deletedPaths.length > 0 || gcResult.failedDeletes.length > 0;
    }

    async function clearAllSummaryVectorIndexCaches_ACU() {
        await Promise.all([
            clearVectorIndexTempCache_ACU(),
            clearSummaryVectorHotCache_ACU(),
        ]);
    }
    function normalizeErrorMessage_ACU(error) {
        if (error instanceof Error)
            return error.message || error.name || '未知错误';
        if (typeof error === 'string')
            return error;
        try {
            const json = JSON.stringify(error);
            return json && json !== '{}' ? json : String(error || '未知错误');
        }
        catch (_jsonError) {
            return String(error || '未知错误');
        }
    }
    function isMissingExternalVectorFileError_ACU(message) {
        const text = String(message || '').toLowerCase();
        const isVectorFileReadFailure = text.includes('交火向量索引分片读取失败')
            || text.includes('交火向量索引内容块读取失败')
            || text.includes('交火向量单文件快照读取失败');
        return isVectorFileReadFailure && /读取失败\s+404(?:\s*:|\b)/.test(text);
    }
    async function clearLatestSummaryVectorIndexStateForMissingExternalFiles_ACU(params) {
        return clearLatestSummaryVectorIndexStateUnderScopeLock_ACU(params, '外置文件缺失');
    }
    async function clearLatestSummaryVectorIndexStateForInvalidExternalFiles_ACU(params) {
        return clearLatestSummaryVectorIndexStateUnderScopeLock_ACU(params, '身份无效');
    }
    async function clearLatestSummaryVectorIndexStateUnderScopeLock_ACU(params, reason) {
        const flushScope = resolveCurrentSummaryVectorFlushScope_ACU({
            isolationKey: params.isolationKey,
            sourceTableKey: params.sourceTableKey,
        });
        return runSummaryVectorIndexArchiveScopeMutationExclusive_ACU(flushScope.scopeKey, async () => {
            // 先持久化失效墓碑，再删除聊天 pointer。该临界区与归档 publish 共用 scope lock，
            // 因此 tombstone 不会在 generation 校验和 durable save 之间插入。
            const flushTaskCountCleared = await clearSummaryVectorIndexFlushQueueForCurrentScopeUnlocked_ACU(flushScope);
            const chatStateCleared = await clearSummaryVectorIndexLayerFromChat_ACU({
                messageIndex: params.messageIndex,
                isolationKey: params.isolationKey,
                indexId: params.indexId,
            });
            const cacheResults = await Promise.allSettled([
                deleteVectorIndexCacheByIndex_ACU(params.indexId),
                deleteSummaryVectorHotCacheByIndex_ACU(params.indexId),
            ]);
            cacheResults.forEach((result, index) => {
                if (result.status === 'rejected') {
                    logWarn_ACU(`[交火向量索引] ${reason} pointer 已删除，但${index === 0 ? '临时' : '热'}缓存清理失败，将继续重建:`, result.reason);
                }
            });
            return {
                chatStateCleared,
                cacheCleared: cacheResults.every((result) => result.status === 'fulfilled'),
                flushTaskCountCleared,
            };
        });
    }
    function isInvalidExternalVectorFileError_ACU(message) {
        const text = String(message || '').toLowerCase();
        return text.includes('交火向量索引分片身份不匹配')
            || text.includes('交火向量索引分片校验失败')
            || text.includes('交火向量索引内容块身份不匹配')
            || text.includes('交火向量索引内容块校验失败')
            || text.includes('交火向量索引内容包身份不匹配')
            || text.includes('交火向量索引内容包校验失败')
            || text.includes('交火向量单文件快照协议不匹配')
            || text.includes('交火向量单文件快照身份不匹配')
            || text.includes('交火向量单文件快照表标识不匹配')
            || text.includes('交火向量单文件快照 v2 身份元数据不完整')
