                }
                logWarn_ACU(clearResult.chatStateCleared
                    ? '[交火向量索引] 当前聊天外置向量文件身份校验失败，已删除失效指针；交由 UI 从源表重建:'
                    : '[交火向量索引] 当前聊天外置向量文件身份校验失败，但失效指针未能安全删除；拒绝盲目重建:', message);
                return {
                    success: clearResult.chatStateCleared,
                    skipped: true,
