        const active = snapshot.storyArc.filter(entry => !entry.retired);
        if (!active.length)
            return `${head}\n当前还没有故事总纲。总纲缺失时无法判断本阶段该走到哪一步，必须先派工 arc-architect 立总纲。`;
        const sorted = [...active].sort(compareStoryArc_ACU);
