    function truncateDetail_ACU(text) {
        if (text.length <= SESSION_DETAIL_LIMIT_ACU)
            return text;
        return `${text.slice(0, SESSION_DETAIL_LIMIT_ACU)}\n（内容过长，已截断）`;
    }
    /**
     * 开始一次新的运行。
