    /** 按 turnKey 的连续段分组。连续段而非全局分组，保证时间顺序不被打乱。 */
    function groupByTurn_ACU(messages) {
        const groups = [];
        for (const message of messages) {
            const tail = groups[groups.length - 1];
            if (tail && tail[0].turnKey === message.turnKey)
                tail.push(message);
            else
                groups.push([message]);
        }
        return groups;
    }
