        const matched = listSheetViews_ACU(tableData).filter(view => view.name === target);
        if (!matched.length)
            return `当前聊天不存在名为「${target}」的表。可用表名见表格目录。`;
        if (matched.length === 1)
            return renderAgentSheet_ACU(matched[0], range);
