        const highestIndex = chat.length - 1;
        if (highestIndex < 0)
            return '当前聊天还没有任何楼层，也就没有已经发生的正文。';
        // 删楼后残留的水位可能指向已不存在的楼层，必须钳制，否则未结算段起点会越过末楼输出空段。
        const settledThrough = Math.min(context.settledThroughIndex, highestIndex);
